"""Generate sfx/SYNTH_API.md (embedded in AI system prompts) from the docstrings of synth.py and ctx.py."""
from __future__ import annotations

import inspect
import textwrap

from . import synth
from .ctx import Ctx

MAX_LINES = 150
WIDTH = 100

HEADER = """\
# vbeat_audio synth API (generated by `python -m vbeat_audio docs`; do not edit by hand)

Cue script: `from synth import *`, define `render(ctx)`, return a mono float array (normally `m.render()`).
Times are seconds, frequencies Hz, levels dB. Sounds are float32 mono, SR=48000, deterministic (seeded).
Recipes peak at 0.5 and last 1.2 s or less. Levels: accent gain_db 0, ordinary -4, soft detail -9.
Imports allowed: numpy, scipy (signal, ndimage, fft), math, functools, itertools, collections, dataclasses,
typing, synth. Refused: open/exec/eval, __dunder__ access, numpy.random and random (use ctx.rng), file I/O,
str.format (use f-strings). Do not iterate a set of strings (random order); use sorted().
Beat-local fields: ctx.sr ctx.fps ctx.samples ctx.dur ctx.words[{id,start,end}] ctx.markers[{id,t,kind}].
"""

SECTIONS = [
    ("ctx", [("ctx.", Ctx, n) for n in ("at", "marker", "marker_times", "rng", "mix")]),
    ("Mix (m = ctx.mix())", [("m.", synth.Mix, n) for n in ("add", "add_group", "render")]),
    ("low level", [("", synth, n) for n in (
        "osc", "noise", "env_adsr", "env_exp", "env_perc", "sweep", "lowpass", "highpass", "bandpass",
        "bandpass_sweep", "resonator", "modal", "echo", "small_room", "soft_clip", "fade", "gain_db",
        "peak_normalize", "concat", "overlay", "silence", "tick_times")]),
    ("recipes", [("", synth, n) for n in (
        "paper_slide", "paper_flick", "page_turn", "pen_tick", "pen_scribble", "soft_pop", "bubble_pop",
        "wood_thunk", "stamp", "swoosh", "click", "chime", "cloth_rustle", "type_keys", "type_key_events",
        "coin_clink", "footstep_soft")]),
]


def _sig(fn, is_method):
    parts = []
    for i, (name, p) in enumerate(inspect.signature(fn).parameters.items()):
        if is_method and name == "self":
            continue
        parts.append(name if p.default is inspect.Parameter.empty else f"{name}={p.default!r}")
    return ", ".join(parts)


def _summary(fn):
    doc = inspect.getdoc(fn)
    if not doc:
        raise ValueError(f"{fn.__qualname__} has no docstring")
    return " ".join(doc.split("\n\n")[0].split())


def generate() -> str:
    """Return the full SYNTH_API.md text; raises when it exceeds 150 lines or a docstring is missing."""
    lines = HEADER.rstrip("\n").split("\n")
    for title, items in SECTIONS:
        lines.append("")
        lines.append(f"## {title}")
        for prefix, owner, name in items:
            fn = getattr(owner, name)
            sig = f"{prefix}{name}({_sig(fn, owner is not synth)})"
            lines += textwrap.wrap(sig, WIDTH, subsequent_indent="    ", break_long_words=False)
            lines += textwrap.wrap(_summary(fn), WIDTH, initial_indent="    ", subsequent_indent="    ")
    if len(lines) > MAX_LINES:
        raise ValueError(f"SYNTH_API.md would have {len(lines)} lines (limit {MAX_LINES}); shorten docstrings")
    return "\n".join(lines) + "\n"
